1.0 {
  global:
    # Taihe ANI entry point
    ANI_Constructor;

    # C++ exception handling runtime (libunwind)
    _Unwind_*;
    unw_local_addr_space;

    # __cfi_check is exported by build/config/sanitizers/cfi.versionscript
    # (cfi_cross_dso = true), do not redeclare here to avoid version conflict.

    extern "C++" {
      # std libc++ RTTI - vtable/VTT/construction vtable only (quoted patterns
      # to avoid matching basic_stringbuf::str/overflow/seekoff/... methods)
      "vtable for std::__h::basic_stringbuf*";
      "vtable for std::__h::basic_ostringstream*";
      "VTT for std::__h::basic_ostringstream*";
      "construction vtable for*-in-std::__h::basic_ostringstream*";

      # Taihe from_ani_t/into_ani_t local static guard variables
      *taihe::from_ani_t*field_2_from_ani*;
      *taihe::into_ani_t*field_4_into_ani*;
      *taihe::into_ani_t*item_into_ani_inner*;
    };

  local:
    *;
};